class SSA(ParentSSA):
 def run(self,f,end):
  for i in f['instructions']:
   pc=int(i['ea'],16)
   if pc>=end:break
   p=split(i['operands'])
   if i['mnemonic']=='stp'and p[0].startswith('w'):
    a=self.address(p[2])
    for j,rd in enumerate(p[:2]):self.stores.append({'site':i['ea'],'address':a if j==0 else f'(bvadd {a} {bv(4)})','value':self.get(rd,32),'width_bits':32})
