def memory_joins():
 # Source frame join, then compositional byte/word lemmas for heap owners.
 decl='(declare-fun M () (Array (_ BitVec 64) (_ BitVec 8)))\n';defs=[]
 def st(mem,a,v,bits,name):
  x=mem
  for j in range(bits//8):x=f'(store {x} (bvadd {a} {bv(j)}) ((_ extract {8*j+7} {8*j}) {v}))'
  defs.append(f'(define-fun {name} () (Array (_ BitVec 64) (_ BitVec 8)) {x})');return name
 def ld(mem,a):return'(concat '+' '.join(f'(select {mem} (bvadd {a} {bv(j)}))'for j in range(7,-1,-1))+')'
 a=frame(0x6520);m=st('M',a,'HROOT',64,'m0');m=st(m,frame(0x4a68),a,64,'m1');m=st(m,frame(0x36c4),'#x8f8d9650',32,'m2');m=st(m,frame(0x5120),a,64,'m3')
 pp=[solve('frame_local_pointer_store_to_cleanup_load',decl+'\n'.join(defs)+'\n'+mismatch([neq(ld(m,a),'HROOT'),neq(ld(m,frame(0x5120)),a),neq(ld(m,frame(0x4a68)),a)]),'All byte-array memories/K/heap values. Exact source frame stores preserve the local builder and two address saves. Native mapping/lifetimes remain unproved.',arrays=True)]
 defs.clear();m=st('M','IN0','IN1',64,'W')
 pp.append(solve('le64_store_load_identity',decl+'\n'.join(defs)+'\n'+mismatch([neq(ld(m,'IN0'),'IN1')]),'All initial byte memories,addresses and values: eight source little-endian bytes reload as the stored full64 word.',arrays=True))
 guard='(and '+' '.join(f'(distinct STR (bvadd IN0 {bv(j)}))'for j in range(8))+')'
 pp.append(solve('store64_preserves_every_other_byte',decl+'\n'.join(defs)+'\n(assert '+guard+')\n'+mismatch([neq('(select W STR)','(select M STR)')]),'Any byte address outside the eight store addresses is unchanged. Combined with source access widths and byte-separation lemmas, this supports independent word-cell effects.',arrays=True))
 for n in [16,128]:
  guard=f'(and (bvult IN0 (bvadd IN0 {bv(n)})) (bvult IN1 (bvadd IN1 {bv(16)})) (bvult LEN {bv(16)}) (bvult STR {bv(16)}) (or (bvule (bvadd IN0 {bv(n)}) IN1) (bvule (bvadd IN1 {bv(16)}) IN0)))'
  pp.append(solve('owner_prefix_byte_separation_'+str(n),'(assert '+guard+')\n(assert (= (bvadd IN0 LEN) (bvadd IN1 STR)))','All nonwrapping disjoint'+str(n)+'/16 B owners and offsets0..15. Thus each eight-byte source cell in either prefix is disjoint from the other owner; this lemma is instantiated for all three owner pairs.'))
 addrs=['CH1','(bvadd CH1 #x0000000000000008)','(bvadd HROOT #x0000000000000008)','CH0','(bvadd CH0 #x0000000000000008)','HROOT'];vals=[bv(0),bv(0),'CH1',bv(0),bv(0),'CH0'];m='MW'
 for a,v in zip(addrs,vals):m=f'(store {m} {a} {v})'
 body='(declare-fun MW () (Array (_ BitVec 64) (_ BitVec 64)))\n(define-fun W64 () (Array (_ BitVec 64) (_ BitVec 64)) '+m+')\n(assert (distinct '+' '.join(addrs)+'))\n'+mismatch([neq(f'(select W64 {a})',v)for a,v in zip(addrs,vals)])
 pp.append(solve('six_word_child_publication_join',body,'Six distinct8 B cells give child0/child1 pointers and zero head/tail words after the exact source write order. Byte-store/load,noninterference and nonwrapping owner-separation lemmas justify this cell abstraction. It is a compositional certificate,not a native owner observation.',arrays=True))
